package org.elasticsearch.xpack.security.cli.bc;

import org.bouncycastle.asn1.x509.KeyPurposeId;

/**
 * The key purposes that can be set in the X.509 <em>Extended Key Usage</em> extension of the certificates and certificate signing
 * requests generated by {@link CertGenUtils}.
 * <p>
 * Each constant maps to a Bouncy Castle {@code KeyPurposeId}, which is not exposed so that callers outside this module do not depend
 * on Bouncy Castle types, which are shaded into this module's jar.
 * </p>
 */
public enum KeyPurpose {
    /**
     * TLS server authentication ({@code id-kp-serverAuth})
     */
    SERVER_AUTH(KeyPurposeId.id_kp_serverAuth),
    /**
     * Any purpose ({@code anyExtendedKeyUsage})
     */
    ANY(KeyPurposeId.anyExtendedKeyUsage);

    private final KeyPurposeId keyPurposeId;

    KeyPurpose(KeyPurposeId keyPurposeId) {
        this.keyPurposeId = keyPurposeId;
    }

    KeyPurposeId keyPurposeId() {
        return keyPurposeId;
    }
}
